function bottom(){const active=['finances','send','deposit','pay','receipt','receipts'].includes(route)?'finances':['rewards','merchant','coupon','school-rewards','school-reward'].includes(route)?'rewards':['messages','chat','contacts'].includes(route)?'messages':route==='settings'||route==='profile'?'settings':'';return `<nav class="bottom" aria-label="Main navigation">${collegeConfig().nav.map(([r,i,l])=>B(`${I(i)}<span>${l}</span>${r==='messages'&&!S.read.includes('Quincy College')?'<b class="badge"></b>':''}`,'navigate',active===r?'active':'',r)).join('')}</nav>`;}
function modal(title,body,buttons=[['OK','close']]){const d=$('#dialog');d.className=(!title&&!body&&buttons.length>=3)?'action-sheet':'';d.innerHTML=`<div class="dialog-panel"><div class="dialog-body">${title?`<h2>${esc(title)}</h2>`:''}${body}</div><div class="dialog-actions">${buttons.map(([l,a,v])=>B(esc(l),a,'',v||'')).join('')}</div></div>`;d.hidden=false;$('#app').inert=true;d.querySelector('input,textarea,button')?.focus();}
function close(){const d=$('#dialog');d.hidden=true;$('#app').inert=false;}
