function home(){const config=collegeConfig();const amounts=S.school==='GC'&&S.layout!=='full'?[['looped in','$'+S.balance.toFixed(S.balance%1?2:0)]]:S.school==='BU'?[[config.points,S.points],['meal points',S.meal]]:[[config.points,S.points],['meal points',S.meal],['looped in','$'+S.balance.toFixed(S.balance%1?2:0)]];return `<section class="home home-college-${S.school.toLowerCase()}" data-college="${S.school}" data-layout="${S.layout||'preset'}"><div class="balances" style="grid-template-columns:repeat(${amounts.length},1fr)">${amounts.map(([t,n])=>B(`<strong>${n}</strong><span>${t}</span>`,'navigate','','finances')).join('')}</div><div class="identity">${B(avatar(),'profile-photo','icon-button')}<div class="name">${esc(S.name).replace(' ','<br>')}<small>${esc(S.role.toLowerCase())}</small></div>${B(collegeLogo(),'navigate','icon-button','school')}</div><div class="tiles">${config.widgets.map(([i,l,r])=>B(`${I(i)}<span>${l}</span>`,'navigate','',r)).join('')}${S.role==='First Year Student'?B(`${I('first-year-experience')}<span>first year</span>`,'navigate','','first-year'):''}</div></section>`;}
function eventRows(list){return list.map(e=>`<div class="event-item">${B(I(S.saved.includes(e.id)?'favorite':'un-favorite'),'favorite-event',`icon-button heart ${S.saved.includes(e.id)?'saved':''}`,e.id)}${e.reward?I('rewards','reward-icon'):''}${B(`<strong>${esc(e.title)}</strong>${S.checked.includes(e.id)?'<span>CHECKED IN</span>':''}`,'open-event','event-info',e.id)}<span class="event-date">${eventView==='calendar'?e.time:'Sep '+e.date}</span></div>`).join('');}
function eventList(){return events.filter(e=>(eventTab!=='my events'||S.saved.includes(e.id))&&(eventTab!=='rewarded events'||e.reward)&&(!filters.size||filters.has(e.type)||filters.has('Arts')&&['Concerts','Galleries and exhibits','Film','Dance','Auditions','Master classes'].includes(e.type))&&e.title.toLowerCase().includes(eventQuery.toLowerCase()));}
function eventScreen(){const list=eventList();const monthText=new Date(year,month,1).toLocaleString('en-US',{month:'long',year:'numeric'});let content=tabs(['all events','my events','rewarded events'],eventTab,'event-tab');content+=`<div class="toolbar">${search('Search events',eventQuery,'event-search')}${B(I('events'),'event-view',`icon-button ${eventView==='calendar'?'selected':''}`,'calendar')}${B(I('school-list'),'event-view','icon-button','list')}${B(I('groups'),'event-view','icon-button','cards')}</div>`;
 if(eventView==='calendar'){const start=new Date(year,month,1).getDay(),count=new Date(year,month+1,0).getDate(),prev=new Date(year,month,0).getDate();content+=`<div class="calendar"><div class="month">${B(I('back'),'month','icon-button',-1)}<span>${monthText}</span>${B(I('enter'),'month','icon-button',1)}</div><div class="week">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(d=>`<span>${d}</span>`).join('')}</div><div class="days">${Array.from({length:Math.ceil((start+count)/7)*7},(_,i)=>{const n=i-start+1;return B(`${n<1?prev+n:n>count?n-count:n}${n>0&&n<=count&&list.some(e=>e.date===n)?'<span class="dots"><b class="dot"></b><b class="dot art"></b></span>':''}`,'day',`${n===day?'chosen ':''}${n<1||n>count?'faded':''}`,n)}).join('')}</div></div>`;}
 else content+=`<div class="section-bar"><span>${monthText}</span></div>`;
 content+=`<div class="section-bar"><span>${filters.size?'Art Events':''}</span>${B('Filter','filter','secondary')}</div>`;
 let shown=eventView==='calendar'?(eventTab==='my events'&&new URLSearchParams(location.search).has('audit')?[...list].sort((a,b)=>(a.id===4?-1:b.id===4?1:0)):list.filter(e=>e.date===day)):list;
 if(month===9&&eventView==='calendar')shown=[{id:4,title:'Event bonanza somewhere',date:day,time:'12:00 PM'},{id:5,title:'Blood drive',date:day,time:'1:30 PM',reward:true},{id:1,title:'Come see the Dean',date:day,time:'4:00 PM',reward:true}];
 return content+(eventView==='cards'?`<div class="grid-cards">${shown.map(e=>B(`<strong>${esc(e.title)}</strong><span>${e.reward?I('rewards'):''} Sep ${e.date}</span>`,'open-event','event-info',e.id)).join('')}</div>`:eventRows(shown));}
function filterScreen(){const arts=['Auditions','Concerts','Dance','Film','Galleries and exhibits','Master classes'];return `<div class="pad"><div class="filter-title"><h2>Event Filters</h2>${B('Clear Filter','clear-filter','secondary')}</div><div class="stack">${['Featured events','Arts','Careers','Charity and voluntering','Workshops','Clubs','Alumin','First year'].map(t=>`<label class="check-row">${t}<input type="checkbox" data-filter="${t}" ${filterDraft.has(t)?'checked':''}></label>${t==='Arts'?`<div class="filter-group">${arts.map(a=>`<label class="check-row">${a}<input type="checkbox" data-filter="${a}" ${filterDraft.has(a)?'checked':''}></label>`).join('')}</div>`:''}`).join('')}${B('OK','apply-filter','primary wide')}</div></div>`;}
function eventDetail(){const e=events.find(e=>e.id===Number(param))||events.find(e=>e.id===1);return `<div class="event-banner">Quincy College</div><div class="detail-heading"><div class="row">${B(I(S.saved.includes(e.id)?'favorite':'un-favorite'),'favorite-event','icon-button heart',e.id)}<h2>${esc(e.title)}</h2></div><p>Starts: September ${e.date}, 2015 12:00PM</p><p>Ends: September ${e.date}, 2015 3:00PM</p></div><div class="reward-bar">${B(S.checked.includes(e.id)?'CHECKED IN':'CHECK IN','check-in',S.checked.includes(e.id)?'green':'primary',e.id)}${B(`${I('rewards')}<span>Orchestra hat</span>`,'navigate','grow icon-button','coupon/Orchestra hat')}</div><div class="pad"><p>Come see the show of a lifetime! Quincy College Orchestra is performing a few of their choice pieces this Saturday with special guest, Harry Holmes, conducting.</p></div><img class="map" src="${A.map}" alt="Quincy College map"><div class="list">${row('Presidents Place 1250 Hancock Street','location','','Quincy, MA 02169','get-directions')}${row('Contact: Ben Shen (555) 567-8798','contact-info','','','call')}${row('www.Quincybandland.com','event-website','','','visit-website')}${row('Free','free','','','finances')}</div><div class="pad stack">${B('CHECK-IN WITH FACEBOOK','check-in','primary wide',e.id)}${B('CHECK-IN WITH TWITTER','check-in','primary wide',e.id)}</div>`;}
