function merchantGrid(isRewards=false){const selected=isRewards?rewardTab:placeTab;return tabs(isRewards?['all merchants','favorites','my rewards']:['all places','favorites','map'],selected,isRewards?'reward-tab':'place-tab')+`<div class="toolbar">${search('Search places','','place-search')}<span class="muted">5 mi | 10 mi</span></div><div id="merchant-results">${selected==='map'?`<button class="wide icon-button" data-action="navigate" data-value="merchant"><img src="${A.map}" alt="Places map" style="width:100%"></button>`:`<div class="merchant-grid">${merchants.filter(([n])=>selected!=='favorites'||S.favorites.includes(n)).map(([n,img])=>`<div class="merchant-card"><button class="icon-button" style="padding:0;width:100%;display:block" data-action="merchant" data-value="${esc(n)}"><img src="${img}" alt="${esc(n)}"></button><div class="caption">${B(I(S.favorites.includes(n)?'favorite':'un-favorite'),'favorite-place','icon-button heart',n)}${B(I('rewards'),'merchant','icon-button',n)}</div></div>`).join('')}</div>`}</div>`;}
