function schoolRewards(){const items=['Concert in Central Hall','Some event for a lot of fun','Check in at 3 art events','Check in at More Art Events Here','fill out waiver online get a highfive','Sign up for orientation, get a meal coupon','Pottery class for a Quincy T-shirt','Other event in Main Hall'];return `<div class="toolbar">${search('Search school rewards','','school-reward-search')}</div><div class="grid-cards" id="school-reward-results">${items.map((r,i)=>B(`<strong>${esc(r)}</strong><small>${i<2?'Sep '+(i?15:1):''}</small>`,'navigate','reward-tile',i===0?'event/1':i===1?'event/2':'school-reward/'+encodeURIComponent(r))).join('')}</div>`;}
function schoolReward(){return `<img class="merchant-image" src="${A.school}" alt="Quincy College"><div class="detail-heading"><h2>${esc(param||'Sign up for orientation, get a meal coupon')}</h2><p>September 8th, 2015 12:30PM</p></div>${row('Meal Coupon','coupon','muffin at the cafeteria','','rewards')}${row('www.orientationpie.com','orientation-info','','','visit-website')}${row('Call (555) 087-0238','orientation-info','','','call')}`;}
function coupon(){const name=param||'muffin at the cafeteria';return `<div class="pad muted">To use, present this page to merchant</div><div class="coupon"><h2>${esc(name)}</h2><p>${name==='Orchestra hat'?'Stop by the main stage after the Concert in Central Hall and recieve a cap with the Quincy College Orchestra logo. Wear your hat with pride!':name==='muffin at the cafeteria'?'Recieve a free muffin with your next visit to Quincy College cafeteria.':''}</p><p class="muted">${name==='Orchestra hat'?'Coupon Valid: September 1st':'Coupon Valid: September 3 - November 22'}<br>This reward can be combined with other offers</p><div class="seal">${I('earned-reward')}</div></div><div class="pad">${B('Where did I get this reward?','reward-origin','primary wide',name)}</div>`;}
